-- 5012 🏋️ Exercises from the book "kindle-footballs-principles-of-play" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'kindle-footballs-principles-of-play');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Two-team end-to-end target passing', 'passing_opposed', 'passive', 'in_possession', 107, 107, 'Penetration', NULL, 'Play forward into a target player while working around the traffic of another team.', 'Rectangular grid with a target player standing off each end line; two teams of four mixed inside the grid, each team with its own ball.', 'Each team passes among itself and then plays into a target at one end; the target gives it back to the same team, which then works the ball through to the opposite target, so teams keep travelling end to end.', 'The two teams do not tackle each other; the other team is only interference to play around.', NULL, 'The pass into the target stands for a forward pass into an attacker; look up and find the lane through the crowd.', '4v4 + 2 end targets (from diagram)', 10, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 10),
  ('Target man lay-off into end zone finish', 'small_sided_game', 'opposed', 'in_possession', 108, 108, 'Penetration II', NULL, 'Penetrate by playing into a striker and finishing from runs into the space behind the defence.', 'Pitch with a goal at each end; an end zone (A) in front of each goal holding only the goalkeeper, then a narrow zone (B) ahead of it for each team''s target striker; the remaining players play in the middle area.', 'Teams try to find their target man in zone B, who sets the ball back or off to supporting team-mates arriving to finish inside zone A.', 'Goals must be scored from inside zone A. Defenders may mark in front of the target man but may not enter zone A or B until the ball has gone in.', 'Alternative: pass straight into zone A for the striker to run onto, copying a ball in behind a back line.', 'Timing of supporting runs off the lay-off; quick forward pass into the striker.', 'Two teams each with a goalkeeper and a target striker, about 6v6 (from diagram)', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 20),
  ('End-to-end switch with half targets', 'positional_game', 'opposed', 'in_possession', 109, 109, 'Support', NULL, 'Supporting movement: whole team shifting to the half the ball is played into and finding new support angles.', 'Area split into two halves with a target zone at each end; each team keeps one target player in each end zone.', 'Teams try to move the ball from one end to the other via their targets; whenever the ball is switched into the other half, every outfield player must move across into that half.', 'All players must relocate to the half the ball has gone into.', NULL, 'React to the ball''s position; look for fresh angles to support the ball carrier.', 'two teams of about 6 incl. 2 targets each', 10, 14, NULL, NULL, NULL, NULL, false, false, true, NULL, 30),
  ('Switch game with one player left behind', 'positional_game', 'opposed', 'in_possession', 110, 110, 'Support II', NULL, 'Individuals finding space and recognising who should support the ball, without fixed targets.', 'Area split into two halves, no target zones; two even teams.', 'When the ball is switched into the other half, each team must leave exactly one player in each half while all others move across; teams choose or rotate who stays based on what they see.', 'Every team must always have one player in each half; no designated locked player.', 'Progression of the Support practice (targets removed).', 'Receiver in the far half must lose his marker; recognise who needs help and who is best placed to give it.', 'two even teams of about 6', 10, 14, NULL, NULL, NULL, NULL, false, false, true, NULL, 40),
  ('Wide-zone double goal game', 'small_sided_game', 'opposed', 'in_possession', 111, 111, 'Width', NULL, 'Using width by exploiting wide areas in the opposition half.', 'Pitch with a goal at each end and wide channels down both sides, split at halfway; each team has two players in the wide zones in the opposition half; defenders may not enter the zones.', 'Normal game to goals; teams may score without the wide players, but a goal that comes after using a wide player counts double.', 'Goal worth double if a wide player was used; no defenders in wide zones; time or touch limit on wide players if they slow play down.', 'Rotation: the wide receiver dribbles inside (or passes and follows) and the passer or nearest player fills the vacated wide spot, like inverted wingers.', 'Look to play wide early; keep tempo in wide zones.', 'e.g. 6v6 incl. GKs and 2 wide players each', 10, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('End-zone runs to score', 'positional_game', 'opposed', 'in_possession', 112, 112, 'Mobility/Movement', NULL, 'Movement off the ball to lose a marker and exploit space behind the defence.', 'Central area with an end zone at each end; each team defends one end zone.', 'Teams score a point by passing to a teammate who has run into the end zone to receive; defenders cannot enter the end zone.', 'Receiver must arrive in the end zone with a run; no defenders in end zones.', 'A point can also be scored by dribbling the ball into the end zone.', 'Spot the space and time the run to lose the marker.', 'two teams of about 5-6', 10, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 60),
  ('Reversed goals on end-zone edge', 'small_sided_game', 'opposed', 'in_possession', 113, 113, 'Improvisation/Creativity', NULL, 'Creativity and improvisation by presenting an unfamiliar scoring problem.', 'Pitch with end zones; goals turned round to face away, placed on the edge of each end zone; a goalkeeper and a forward start in each end zone.', 'Teams play into the end zone (pass or dribble) and then can enter to score into the back-facing goal; the GK may mark the forward, forcing different movements and finishes.', 'Players only enter the end zone after the ball has been passed or dribbled in.', NULL, 'Find new ways to create chances through movement, support and quick finishing.', 'two teams of about 6 incl. GK', 10, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Delay the overload until recovery', 'phase_of_play', 'overload', 'out_of_possession', 114, 114, 'Delay', NULL, 'Defenders delaying an overloaded attack until recovering teammates get back.', 'Area split in two halves, goal at one end; in the goal half 2 dark defenders plus GK and a grey striker; in the other half 2 grey attackers, with 1 grey and 2 dark players waiting on the far end line.', 'Grey on the line passes in and joins the attack to goal; the two dark players on the line set off on recovery runs once the receiver controls it; the two dark defenders try to delay until help arrives.', 'If dark win the ball they score by crossing the end line where play started.', NULL, 'Delay, do not dive in; buy time for recovering runners to reverse the overload.', '4v2+GK, then 4v4+GK', 8, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Low, medium and high block zones', 'defending', 'opposed', 'out_of_possession', 115, 115, 'Depth', NULL, 'Defending at different heights of engagement (low, mid, high block) with discipline and positioning.', 'Pitch split into thirds (low, medium, high) with a halfway line for offside; dark attack one goal while grey defend; spare balls by the dark goal.', 'Three 5-minute blocks: grey defend low (no pressure until the opposition crosses halfway, most defenders in the low third), then medium engagement, then high engagement with most in the high third and nobody in the low third.', 'Halfway line used for offside.', NULL, 'Stay disciplined to the chosen line of engagement; patience and positioning.', 'e.g. 7v6 incl. GKs', 12, 16, NULL, NULL, NULL, 15.0, true, true, true, NULL, 90),
  ('Breaking a compact low block', 'phase_of_play', 'opposed', 'out_of_possession', 116, 116, 'Compactness', NULL, 'Defensive compactness: shifting together and screening the centre against a team trying to break through.', 'Grey defend one big goal in their own half in a low block (back four plus midfield line); dark attack, with wide channels available; three mini-goals at the far end for grey to counter into.', 'Dark try to break through the block, using the wide areas; grey shift across with the ball keeping short distances; if grey win it they can score in any of the three mini-goals.', 'If the ball goes wide only one grey player (full-back) may go out to pressure the cross.', 'Dark can add more strikers; grey can switch to a back three plus an extra midfielder.', 'Watch the ball, the nearest opponent and teammates; midfielders screen the striker.', 'e.g. 10 grey + GK v 7 dark', 16, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Wide pitch backline balance', 'defending', 'opposed', 'out_of_possession', 117, 117, 'Balance', NULL, 'Defensive balance: shifting the back line with the ball and conceding the far side.', 'Pitch wider than it is long; four mini-goals on the attacking line, an end zone at the other end.', 'Dark attack the four mini-goals; grey shift across to block the path from ball to goal, leaving the player furthest from the ball free; if grey win it they score by dribbling or passing to a runner into the end zone.', 'Grey score only via the end zone.', NULL, 'Stay compact near the ball but never leave a gap too big to cover.', 'about 5v5', 10, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 110),
  ('Three-zone interception game', 'rondo', 'opposed', 'out_of_possession', 118, 118, 'Discipline/Patience', NULL, 'Patience and discipline both for the team passing and the team trying to intercept.', 'Area split into thirds; white team in one end zone, dark team in the other, grey team in the middle zone.', 'White and dark pass low across the middle to each other; grey shift to block lanes and look to intercept; if grey intercept they swap with the team that lost it.', 'Passes must be along the ground; the intercepting team must immediately pass to the team that did not give the ball away.', NULL, 'Communicate and move together, cut angles, wait for the interception.', '3 teams of 4', 12, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 120),
  ('Quick restart counter-attack game', 'transition', 'opposed', 'to_attack', 119, 119, 'Counter-Attack', NULL, 'Fast reaction to a transition by changing the restart law.', 'Pitch with two goals; each team has a player with spare balls standing outside, near the opposition goal.', 'Whenever the ball goes out, the nominated player near the goal restarts immediately by dribbling or passing in to attack; he stays on until the ball goes out again, then returns to his outside spot if his team has the ball.', 'No goal kicks; restarts come from the outside player near the opposing goal.', NULL, 'Focus on reactions of the wide player, teammates and defenders rather than the first pass.', 'e.g. 6v6 incl. GKs', 12, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 130),
  ('4v4+3 counter-press rondo', 'transition', 'opposed', 'to_defend', 120, 120, 'Counter-Press', 'Guardiola', 'Pressing aggressively immediately after losing the ball and pressing on triggers once settled.', 'Rectangle with 4 dark players on the ends (two each end), 4 grey inside, and 3 white neutrals (one top, one bottom on the line, one free inside).', 'Dark keep the ball with white support while grey press; if grey win it they swap to the end positions and dark become pressers.', 'Neutrals on the lines may move along their line; central neutral moves anywhere.', NULL, 'Team losing the ball presses with ferocity at once; later, press on triggers (poor pass, ball in the air) and cut lanes to isolate the ball 2v1.', '4v4+3', 11, 11, NULL, NULL, NULL, NULL, false, false, false, NULL, 140),
  ('Build-out from goal kick to mini-goals', 'phase_of_play', 'opposed', 'in_possession', 121, 121, 'Possession and building out from the back', NULL, 'Building out from the back from a goal kick against a press.', 'Just under two-thirds of a pitch; grey GK starts every attack with a goal kick, three mini-goals beyond halfway; dark defend and attack the big goal.', 'Grey try to play out and score in any mini-goal once over halfway; dark try to win it and score in the big goal; GK may go short or chip over a high press.', 'Grey can only score after crossing halfway; every restart is a GK goal kick.', 'Dark may choose to press high or sit off.', 'Width and central movement to open passing lanes.', 'e.g. 9+GK v 7', 16, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Half-space double goal game', 'small_sided_game', 'opposed', 'in_possession', 122, 122, 'Half-Spaces', NULL, 'Exploiting the half-spaces through movement.', 'Pitch with two goals marked into five vertical channels; the two channels between centre and wings are the half-spaces (A), left empty at the start; wide players outside.', 'Normal game; anyone may move into a half-space at any time.', 'Goal counts double if the assist (or the pass before it) comes from a half-space.', NULL, 'When someone moves into the half-space, another player may need to fill the position left.', 'e.g. 7v7 incl. GKs', 12, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Protect the triangle, show outside', 'defending', 'opposed', 'out_of_possession', 123, 123, 'Showing Outside', NULL, 'Protecting the middle and forcing play wide.', 'Grey defend one big goal and attack two small goals; a triangle marked in front of grey''s goal.', 'Dark attack; grey move as a unit to keep the ball out of the triangle with tight gaps; on a regain grey counter into the small goals.', 'Ball must not enter the triangle.', NULL, 'Patience and shape; gaps tight enough that a pass inside is not on.', 'e.g. 9+GK v 7', 16, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('1v1 hexagon panna arena', 'one_v_one', 'opposed', 'in_possession', 124, 124, 'Deception/Surprise', NULL, 'Deception and surprise in individual 1v1 play.', 'Hexagonal arena with a mini-goal at each end.', '1v1, each player attacks one mini-goal.', 'Goal = 1 point; a nutmeg = 5 points.', NULL, 'Manipulate, tempt and deceive the opponent.', '1v1', 2, 2, NULL, NULL, NULL, NULL, true, false, true, NULL, 180),
  ('Four-goal multidirectional game', 'small_sided_game', 'opposed', 'in_possession', 125, 125, 'Deception/Surprise II', NULL, 'Fakes and deception in a multidirectional game.', 'Square with a goal on each side.', 'Two teams play to all four goals; the first team to score in all four wins; after conceding, a team restarts from the goal just scored in.', 'A team cannot score again in a goal it has already scored in.', NULL, 'Use the many directions to fake and wrong-foot; harder as scoring options shrink.', '4v4', 8, 8, NULL, NULL, NULL, NULL, true, false, true, NULL, 190),
  ('Empty middle third receiving game', 'small_sided_game', 'opposed', 'in_possession', 126, 126, 'Mobility', NULL, 'Forwards dropping into space between the lines and support runs.', 'Pitch in thirds, middle third empty; each team has 3 defenders and a GK in its defending third and 2 attackers in its attacking third.', 'One attacker may drop into the middle third to receive; defenders may not follow; the passer can then make an under/overlap run, or another player runs forward if the GK played it.', 'Only one attacker can enter the middle third; defenders cannot follow.', 'Switch rules so a defender may step into the middle to receive.', 'Lose the marker by dropping; wide runs to support.', '6v6 incl. GKs', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('1v1 to two goals with servers', 'finishing', 'opposed', 'in_possession', 127, 127, 'Economy', NULL, 'Fast finishing with economy of touches after deceptive movement.', 'Area with a goal and GK at each end; three servers with balls on each side line (mixed teams); one grey and one dark in the middle.', 'The central pair play 1v1; the attacker receives from any teammate server and tries to score, then gets another ball; if the other wins it he attacks; ball out or GK save means the other player receives next.', 'Both can score in either goal.', 'Extra points for a one-touch finish.', 'Orientated first touch to shoot fast; communicate so only one server passes.', '1v1 + 6 servers + 2 GKs', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 210),
  ('End-zone safe drop to mini-goals', 'positional_game', 'opposed', 'in_possession', 128, 128, 'Reserve', NULL, 'Using a reserve player who drops into a safe zone to receive and see the play.', 'Area with an end zone at each end, two mini-goals behind each end.', 'Each team attacks two mini-goals; its own defensive end zone is a safe zone for a player to drop into and receive, or a player can be kept there.', 'Cannot shoot until in the attacking end zone.', NULL, 'Reserve player has space and an open body to survey the pitch, like a quarterback.', '5v5', 10, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 220),
  ('Counter-press central box game', 'transition', 'overload', 'to_defend', 129, 129, 'Counter-Press II', NULL, 'Pressing together and blocking lanes after losing it, with goals as a target.', 'Central box with greys around it and one grey inside; three dark inside; a goal at each end beyond end zones.', 'Greys score a point when the central grey receives and plays out to a different grey; dark try to win it and can score in either goal; when grey lose it all of them can leave positions to win it back.', 'Central grey must play out to someone other than the passer.', NULL, 'Dark: press the central players together and block the pass into him rather than chasing the outside players.', '5v3', 8, 8, NULL, NULL, NULL, NULL, true, false, true, NULL, 230),
  ('Side-by-side 3v3 chaos games', 'small_sided_game', 'opposed', 'in_possession', 130, 130, 'Exploit and find space', NULL, 'Scanning and finding space when the area becomes chaotic.', 'Two 3v3 games side by side, each with a goal at each end.', 'Phase 1: two normal 3v3s; phase 2: dividing line removed and teams play diagonally across the whole area; phase 3: teams play the other team that shares their goal line.', NULL, NULL, 'Observe the area and move to the space that appears among the interference.', '4 teams of 3', 12, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 240),
  ('Horizontal 1v1 to mini-goals', 'one_v_one', 'opposed', 'in_possession', 131, 131, 'One versus one domination', NULL, 'Twisting and turning, changing direction horizontally in a 1v1.', 'Area with end zones at each end and a mini-goal on each end; dark line on one side, grey line on the other at halfway.', 'Grey passes across to dark, who attacks either mini-goal; if grey win it he can score in either too; players then join the opposite line.', 'Can only shoot from inside an end zone.', NULL, NULL, '1v1 from two lines', 6, 10, NULL, NULL, NULL, NULL, true, false, true, NULL, 250),
  ('Direct 1v1 dribbling to mini-goals', 'one_v_one', 'opposed', 'in_possession', 132, 132, 'One versus one domination II', NULL, 'Direct dribbling, changing direction vertically in a 1v1.', 'Area with end zones; two mini-goals at each end; grey line at one end, dark line at the other.', 'Grey passes the length to dark, who attacks the two mini-goals at the grey end once in the end zone; if grey win it he scores in the goals behind dark; players then swap lines.', 'Shoot only from inside the end zone.', NULL, NULL, '1v1 from two lines', 6, 10, NULL, NULL, NULL, NULL, true, false, true, NULL, 260),
  ('3v1 rondo with an empty side', 'rondo', 'opposed', 'in_possession', 133, 133, 'Diamonds and triangles', NULL, 'Moving to create triangles and fill the open side.', 'Square with three outside players on three sides, one side left empty, one defender in the middle.', 'Outside players pass while moving along the lines to keep triangles, recognising when to shift round to fill the empty side.', 'If the middle player wins it he swaps with whoever lost it.', NULL, 'Move early to keep two passing options.', '3v1', 4, 4, NULL, NULL, NULL, NULL, false, false, false, NULL, 270),
  ('Small-sided game with outside wingers', 'small_sided_game', 'opposed', 'in_possession', 134, 134, 'Diamonds and triangles II', NULL, 'Creating diamonds and triangles between inside players and outside support.', 'Pitch with two goals and GKs, white support players on each touchline.', 'Outside whites move along the wings to support; inside players move to support after the outside player receives, keeping diamonds and triangles together.', NULL, 'Progression of the 3v1 triangle rondo.', 'Keep shapes linked with outside players.', 'e.g. 4v4 + GKs + 2 neutrals', 10, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Three-zone overload by following pass', 'small_sided_game', 'opposed', 'in_possession', 135, 135, 'Create Overloads', NULL, 'Creating overloads through movement into the next zone.', 'Pitch in thirds; each team has 3 in its defensive third (incl. GK), 2 in midfield and 2 in attack.', 'An outfield player who passes into the next zone may follow the pass to make an overload; out-of-possession players stay locked in their zone.', 'Defenders locked in zones.', 'Overload also by dribbling into the next zone or dropping into the ball zone; GK gives an automatic overload at the back.', NULL, '7v7 incl. GKs', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 290)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'kindle-footballs-principles-of-play') b;
INSERT INTO schema_migrations (filename) VALUES ('5012-exercises-book-kindle-footballs-principles-of-play.sql') ON CONFLICT DO NOTHING;
COMMIT;
